static NSString *ColorString(UIColor *c) {
    if (!c) return @"(nil)";
    CGFloat r=0,g=0,b=0,a=0;
    if ([c getRed:&r green:&g blue:&b alpha:&a]) return [NSString stringWithFormat:@"rgba(%.3f, %.3f, %.3f, %.3f)",r,g,b,a];
    CGFloat w=0;
    if ([c getWhite:&w alpha:&a]) return [NSString stringWithFormat:@"gray(%.3f, %.3f)",w,a];
    return c.description;
}
static NSString *LayerColorString(CGColorRef color) { return color ? ColorString([UIColor colorWithCGColor:color]) : @"(nil)"; }
static NSString *ViewLine(UIView *v) {
    return [NSString stringWithFormat:@"%@ %p frame=%@ bounds=%@ alpha=%.2f hidden=%@ bg=%@ layerBg=%@", NSStringFromClass(v.class),v,NSStringFromCGRect(v.frame),NSStringFromCGRect(v.bounds),v.alpha,v.hidden?@"YES":@"NO",ColorString(v.backgroundColor),LayerColorString(v.layer.backgroundColor)];
}

static NSURL *ReportsDirectory(void) {
    NSURL *documents = [[[NSFileManager defaultManager] URLsForDirectory:NSDocumentDirectory inDomains:NSUserDomainMask] firstObject];
    NSURL *dir = [documents URLByAppendingPathComponent:UIID isDirectory:YES];
    [[NSFileManager defaultManager] createDirectoryAtURL:dir withIntermediateDirectories:YES attributes:nil error:nil];
    return dir;
}
static void WriteReport(NSString *name, NSString *text) {
    NSURL *url = [ReportsDirectory() URLByAppendingPathComponent:name];
    [text writeToURL:url atomically:YES encoding:NSUTF8StringEncoding error:nil];
}
static NSString *ReportPath(NSString *name) { return [[ReportsDirectory() URLByAppendingPathComponent:name] path]; }

// Small uncompressed ZIP writer: creates a standards-compliant ZIP without third-party code.
static void ZipU16(NSMutableData *d, uint16_t v) { [d appendBytes:&v length:2]; }
static void ZipU32(NSMutableData *d, uint32_t v) { [d appendBytes:&v length:4]; }
static NSData *ZipData(NSDictionary<NSString *,NSData *> *files) {
    NSMutableData *zip=[NSMutableData data]; NSMutableArray<NSData *> *central=[NSMutableArray array];
    for (NSString *name in files) {
        NSData *data=files[name]; NSData *nameData=[name dataUsingEncoding:NSUTF8StringEncoding]; uint32_t crc=(uint32_t)crc32(0,(const Bytef *)data.bytes,(uInt)data.length); uint32_t size=(uint32_t)data.length; uint32_t offset=(uint32_t)zip.length;
        // Local file header: signature, version, UTF-8 flag, stored method, times, CRC, sizes, name and extra lengths.
        ZipU32(zip,0x04034b50); ZipU16(zip,20); ZipU16(zip,0x0800); ZipU16(zip,0); ZipU16(zip,0); ZipU16(zip,0); ZipU32(zip,crc); ZipU32(zip,size); ZipU32(zip,size); ZipU16(zip,(uint16_t)nameData.length); ZipU16(zip,0); [zip appendData:nameData]; [zip appendData:data];
        NSMutableData *c=[NSMutableData data];
        // Central directory header.
        ZipU32(c,0x02014b50); ZipU16(c,20); ZipU16(c,20); ZipU16(c,0x0800); ZipU16(c,0); ZipU16(c,0); ZipU16(c,0); ZipU32(c,crc); ZipU32(c,size); ZipU32(c,size); ZipU16(c,(uint16_t)nameData.length); ZipU16(c,0); ZipU16(c,0); ZipU16(c,0); ZipU16(c,0); ZipU32(c,0); ZipU32(c,offset); [c appendData:nameData]; [central addObject:c];
    }
    uint32_t centralOffset=(uint32_t)zip.length; for(NSData *c in central)[zip appendData:c]; uint32_t centralSize=(uint32_t)zip.length-centralOffset;
    ZipU32(zip,0x06054b50); ZipU16(zip,0); ZipU16(zip,0); ZipU16(zip,(uint16_t)central.count); ZipU16(zip,(uint16_t)central.count); ZipU32(zip,centralSize); ZipU32(zip,centralOffset); ZipU16(zip,0); return zip;
}


static BOOL ValidateZipArchive(NSData *data, NSUInteger *fileCount, NSString **reason) {
    const uint8_t *b=data.bytes; NSUInteger n=data.length; if(n<22){if(reason)*reason=@"archive shorter than EOCD";return NO;} NSInteger e=-1; for(NSInteger i=(NSInteger)n-22;i>=0 && i>(NSInteger)n-65558;i--){if(*(uint32_t *)(b+i)==0x06054b50){e=i;break;}} if(e<0){if(reason)*reason=@"end-of-central-directory signature not found";return NO;} uint16_t count=*(uint16_t *)(b+e+10); uint32_t size=*(uint32_t *)(b+e+12), off=*(uint32_t *)(b+e+16); if((NSUInteger)off+size>(NSUInteger)e){if(reason)*reason=@"central directory bounds invalid";return NO;} NSUInteger pos=off, seen=0; while(pos<(NSUInteger)off+size){if(pos+46>n || *(uint32_t *)(b+pos)!=0x02014b50){if(reason)*reason=@"central directory entry invalid";return NO;} uint16_t nl=*(uint16_t *)(b+pos+28), extra=*(uint16_t *)(b+pos+30), comment=*(uint16_t *)(b+pos+32); if(pos+46+nl+extra+comment>n){if(reason)*reason=@"central entry length invalid";return NO;} pos+=46+nl+extra+comment; seen++;} if(seen!=count){if(reason)*reason=[NSString stringWithFormat:@"entry count mismatch expected=%u seen=%lu",count,(unsigned long)seen];return NO;} if(fileCount)*fileCount=seen; return YES;
}


static uint64_t CurrentMemoryBytes(void) { mach_task_basic_info_data_t info; mach_msg_type_number_t count=MACH_TASK_BASIC_INFO_COUNT; kern_return_t kr=task_info(mach_task_self(),MACH_TASK_BASIC_INFO,(task_info_t)&info,&count); return kr==KERN_SUCCESS ? (uint64_t)info.resident_size : 0; }
static NSTimeInterval PhaseClock(void) { return CACurrentMediaTime(); }
static void AppendPhaseLog(NSString *phase, NSString *state, NSTimeInterval started, NSUInteger count, NSUInteger bytes, NSString *error) { NSString *line=[NSString stringWithFormat:@"%@ phase=%@ state=%@ elapsed_ms=%.1f count=%lu bytes=%lu memory_bytes=%llu error=%@\n",[NSDate date],phase,state,(PhaseClock()-started)*1000.0,(unsigned long)count,(unsigned long)bytes,(unsigned long long)CurrentMemoryBytes(),error ?: @"-"]; NSURL *u=[ReportsDirectory() URLByAppendingPathComponent:@"SESSION_PHASE_LOG.txt"]; NSFileHandle *h=[NSFileHandle fileHandleForWritingAtPath:u.path]; if(!h){[line writeToURL:u atomically:YES encoding:NSUTF8StringEncoding error:nil];return;} [h seekToEndOfFile]; [h writeData:[line dataUsingEncoding:NSUTF8StringEncoding]]; [h closeFile]; }
static NSData *BoundedFileData(NSURL *url, NSUInteger maxBytes, BOOL *truncated) { NSData *d=[NSData dataWithContentsOfURL:url]; if(d.length>maxBytes){if(truncated)*truncated=YES; return [d subdataWithRange:NSMakeRange(0,maxBytes)];} return d ?: [NSData data]; }
static NSUInteger WriteDetailedRuntimeReport(NSURL *url, NSUInteger maxClasses, NSUInteger maxMethods, NSUInteger maxBytes, BOOL *truncated, NSString **errorOut) {
    FILE *f=fopen(url.path.UTF8String,"wb"); if(!f){if(errorOut)*errorOut=[NSString stringWithFormat:@"open failed: %s",strerror(errno)];return 0;} NSUInteger classes=0,methods=0,bytes=0; int n=objc_getClassList(NULL,0); Class *cs=(Class *)malloc(sizeof(Class)*MAX(n,0)); n=objc_getClassList(cs,n); for(int i=0;i<n && classes<maxClasses && bytes<maxBytes;i++){Class c=cs[i]; const char *img=class_getImageName(c); if(img && (strstr(img,"/System/")||strstr(img,"/usr/lib/")||strstr(img,"/Developer/"))) continue; NSString *head=[NSString stringWithFormat:@"CLASS %@ : %@ image=%@\n",NSStringFromClass(c),NSStringFromClass(class_getSuperclass(c)),img ? [NSString stringWithUTF8String:img] : @"(nil)"]; NSData *hd=[head dataUsingEncoding:NSUTF8StringEncoding]; if(bytes+hd.length>maxBytes)break; fwrite(hd.bytes,1,hd.length,f);bytes+=hd.length;classes++; unsigned mc=0; Method *ms=class_copyMethodList(c,&mc); for(unsigned j=0;j<mc && methods<maxMethods && bytes<maxBytes;j++){Method m=ms[j]; NSString *line=[NSString stringWithFormat:@"  declared instance selector=%@ types=%s imp=%p\n",NSStringFromSelector(method_getName(m)),method_getTypeEncoding(m),method_getImplementation(m)]; NSData *ld=[line dataUsingEncoding:NSUTF8StringEncoding]; if(bytes+ld.length>maxBytes){if(truncated)*truncated=YES;break;} fwrite(ld.bytes,1,ld.length,f);bytes+=ld.length;methods++;} free(ms); if(bytes>=maxBytes){if(truncated)*truncated=YES;break;} mc=0; Method *cms=class_copyMethodList(object_getClass(c),&mc); for(unsigned j=0;j<mc && methods<maxMethods && bytes<maxBytes;j++){Method m=cms[j]; NSString *line=[NSString stringWithFormat:@"  declared class selector=%@ types=%s imp=%p\n",NSStringFromSelector(method_getName(m)),method_getTypeEncoding(m),method_getImplementation(m)]; NSData *ld=[line dataUsingEncoding:NSUTF8StringEncoding]; if(bytes+ld.length>maxBytes){if(truncated)*truncated=YES;break;} fwrite(ld.bytes,1,ld.length,f);bytes+=ld.length;methods++;} free(cms); } free(cs); fclose(f); if(classes>=maxClasses||methods>=maxMethods)if(truncated)*truncated=YES; return bytes;
}

static void AppendViewTree(UIView *v, NSUInteger depth, NSUInteger *nodes, NSMutableString *out) {
    if (!v || depth>kMaxStartupDepth || *nodes>=kMaxStartupNodes) return; (*nodes)++;
    [out appendFormat:@"%@%@\n", [@"" stringByPaddingToLength:depth*2 withString:@" " startingAtIndex:0], ViewLine(v)];
    for (UIView *child in [v.subviews copy]) AppendViewTree(child,depth+1,nodes,out);
}
static UIWindow *FindHostWindow(UIWindowScene **sceneOut, NSString **evidence) {
    UIApplication *app=UIApplication.sharedApplication; NSMutableString *log=[NSMutableString string]; UIWindow *best=nil; UIWindowScene *bestScene=nil;
    for (UIScene *s in app.connectedScenes) {
        if (![s isKindOfClass:UIWindowScene.class]) continue; UIWindowScene *ws=(UIWindowScene *)s;
        [log appendFormat:@"scene=%p state=%ld windows=%lu\n",ws,(long)ws.activationState,(unsigned long)ws.windows.count];
        if (ws.activationState!=UISceneActivationStateForegroundActive && ws.activationState!=UISceneActivationStateForegroundInactive) continue;
        for (UIWindow *w in ws.windows) { [log appendFormat:@"  window=%p hidden=%@ level=%.1f root=%@\n",w,w.hidden?@"YES":@"NO",w.windowLevel,w.rootViewController?NSStringFromClass(w.rootViewController.class):@"(nil)"]; if (!w.hidden && w.rootViewController && w.windowLevel==UIWindowLevelNormal && w.bounds.size.width>0 && w.bounds.size.height>0) { best=w; bestScene=ws; break; } }
        if (best) break;
    }
    if (sceneOut) *sceneOut=bestScene; if (evidence) *evidence=log; return best;
}

