@end

static void SessionViewSnapshot(UIView *v, NSUInteger depth, NSUInteger *nodes, NSUInteger limit, NSMutableArray *out, NSHashTable *seen) {
    if (!v || depth>8 || *nodes>=limit || [seen containsObject:v]) return;
    [seen addObject:v]; (*nodes)++;
    NSMutableDictionary *d=[@{ @"class":NSStringFromClass(v.class), @"superclass":NSStringFromClass(v.superclass), @"address":[NSString stringWithFormat:@"%p",v], @"frame":NSStringFromCGRect(v.frame), @"bounds":NSStringFromCGRect(v.bounds), @"alpha":@(v.alpha), @"hidden":@(v.hidden), @"opaque":@(v.opaque), @"backgroundColor":ColorString(v.backgroundColor), @"layerClass":NSStringFromClass(v.layer.class), @"cornerRadius":@(v.layer.cornerRadius), @"borderWidth":@(v.layer.borderWidth), @"borderColor":LayerColorString(v.layer.borderColor), @"sublayerCount":@(v.layer.sublayers.count), @"accessibilityIdentifier":v.accessibilityIdentifier ?: @"", @"superview":v.superview ? NSStringFromClass(v.superview.class) : @"(nil)" } mutableCopy];
    if ([v isKindOfClass:UIScrollView.class]) { UIScrollView *sv=(UIScrollView *)v; d[@"contentOffset"]=NSStringFromCGPoint(sv.contentOffset); d[@"contentSize"]=NSStringFromCGSize(sv.contentSize); }
    if ([v isKindOfClass:UICollectionViewCell.class] || [v isKindOfClass:UITableViewCell.class]) d[@"visibleCellClass"]=NSStringFromClass(v.class);
    [out addObject:d]; for(UIView *child in [v.subviews copy]) SessionViewSnapshot(child,depth+1,nodes,limit,out,seen);
}
static void SessionControllerSnapshot(UIViewController *vc, NSUInteger depth, NSUInteger *nodes, NSMutableArray *out, NSHashTable *seen) {
    if(!vc||depth>16||*nodes>=500||[seen containsObject:vc]) return; [seen addObject:vc]; (*nodes)++;
    NSMutableDictionary *d=[@{ @"class":NSStringFromClass(vc.class), @"superclass":NSStringFromClass(vc.superclass), @"address":[NSString stringWithFormat:@"%p",vc], @"childCount":@(vc.childViewControllers.count), @"presented":vc.presentedViewController ? NSStringFromClass(vc.presentedViewController.class) : @"(nil)" } mutableCopy];
    if([vc isKindOfClass:UINavigationController.class]) d[@"navigationStack"]=[[(UINavigationController *)vc viewControllers] valueForKeyPath:@"class.description"] ?: @[];
    if([vc isKindOfClass:UITabBarController.class]) d[@"selectedTab"]=(NSStringFromClass(((UITabBarController *)vc).selectedViewController.class) ?: @"(nil)");
    [out addObject:d]; for(UIViewController *c in vc.childViewControllers) SessionControllerSnapshot(c,depth+1,nodes,out,seen); SessionControllerSnapshot(vc.presentedViewController,depth+1,nodes,out,seen);
}
@implementation SessionCapture
+ (instancetype)shared { static SessionCapture *x; static dispatch_once_t once; dispatch_once(&once,^{x=[self new];}); return x; }
- (instancetype)init { if((self=[super init])) _snapshots=[NSMutableArray array]; return self; }
- (void)sceneChanged:(NSNotification *)note { if(!self.active||!self.hostWindow)return; dispatch_after(dispatch_time(DISPATCH_TIME_NOW,(int64_t)(.5*NSEC_PER_SEC)),dispatch_get_main_queue(),^{ if(self.active)[self capture:self.hostWindow label:@"scene-activation" inspectorWindow:nil]; }); }
- (void)start:(UIWindow *)host { self.hostWindow=host; NSAssert(NSThread.isMainThread, @"UIKit capture must start on main"); self.sessionID=[NSUUID UUID].UUIDString; self.snapshots=[NSMutableArray array]; self.active=YES; [[NSNotificationCenter defaultCenter] addObserver:self selector:@selector(sceneChanged:) name:UIApplicationDidBecomeActiveNotification object:nil]; [self capture:host label:@"session-start" inspectorWindow:nil]; }
- (void)capture:(UIWindow *)host label:(NSString *)label inspectorWindow:(UIWindow *)inspector { if(!NSThread.isMainThread||!host||!self.active)return; NSUInteger vn=0,cn=0; NSMutableArray *views=[NSMutableArray array],*controllers=[NSMutableArray array]; SessionViewSnapshot(host,0,&vn,1200,views,[NSHashTable weakObjectsHashTable]); SessionControllerSnapshot(host.rootViewController,0,&cn,controllers,[NSHashTable weakObjectsHashTable]); NSMutableDictionary *snap=[@{ @"sessionID":self.sessionID ?: @"", @"captureID":[NSUUID UUID].UUIDString, @"timestamp":[NSDate date].description, @"label":label ?: @"", @"scene":host.windowScene ? host.windowScene.session.persistentIdentifier : @"", @"hostWindow":[NSString stringWithFormat:@"%p",host], @"views":views, @"controllers":controllers, @"truncated":@(vn>=2000||cn>=500), @"viewCount":@(vn), @"controllerCount":@(cn) } mutableCopy];
    UIGraphicsImageRenderer *renderer=[[UIGraphicsImageRenderer alloc] initWithSize:host.bounds.size]; UIImage *image=[renderer imageWithActions:^(UIGraphicsImageRendererContext *ctx){ [host drawViewHierarchyInRect:host.bounds afterScreenUpdates:NO]; }]; snap[@"screenshotData"]=UIImagePNGRepresentation(image) ?: [NSData data];
    NSDictionary *last=self.snapshots.lastObject; if(last && [last[@"views"] isEqual:views] && [last[@"controllers"] isEqual:controllers] && [last[@"label"] isEqual:label]) return; [self.snapshots addObject:snap];
}
- (void)stop { self.active=NO; [[NSNotificationCenter defaultCenter] removeObserver:self name:UIApplicationDidBecomeActiveNotification object:nil]; }
- (NSURL *)stageSession:(UIWindow *)host error:(NSError **)error { if(NSThread.isMainThread){[self capture:host label:@"export" inspectorWindow:nil];} NSURL *base=[NSURL fileURLWithPath:[NSTemporaryDirectory() stringByAppendingPathComponent:[NSString stringWithFormat:@"%@",self.sessionID ?: [NSUUID UUID].UUIDString]] isDirectory:YES]; [[NSFileManager defaultManager] createDirectoryAtURL:base withIntermediateDirectories:YES attributes:nil error:error]; if(error&&*error)return nil; [[NSFileManager defaultManager] createDirectoryAtURL:[base URLByAppendingPathComponent:@"Screens"] withIntermediateDirectories:YES attributes:nil error:nil]; NSMutableArray *index=[NSMutableArray array]; for(NSDictionary *snap in self.snapshots){ NSString *cid=snap[@"captureID"]; NSURL *dir=[[base URLByAppendingPathComponent:@"Screens"] URLByAppendingPathComponent:cid isDirectory:YES]; [[NSFileManager defaultManager] createDirectoryAtURL:dir withIntermediateDirectories:YES attributes:nil error:nil]; NSMutableDictionary *copy=[snap mutableCopy]; NSData *png=copy[@"screenshotData"]; [copy removeObjectForKey:@"screenshotData"]; [copy removeObjectForKey:@"views"]; [copy removeObjectForKey:@"controllers"]; [index addObject:copy]; [NSJSONSerialization dataWithJSONObject:snap[@"views"] options:NSJSONWritingPrettyPrinted error:nil]; [[NSJSONSerialization dataWithJSONObject:snap[@"views"] options:NSJSONWritingPrettyPrinted error:nil] writeToURL:[dir URLByAppendingPathComponent:@"views.json"] atomically:YES]; [[NSJSONSerialization dataWithJSONObject:snap[@"controllers"] options:NSJSONWritingPrettyPrinted error:nil] writeToURL:[dir URLByAppendingPathComponent:@"controllers.json"] atomically:YES]; [png writeToURL:[dir URLByAppendingPathComponent:@"screenshot.png"] atomically:YES]; } NSData *idx=[NSJSONSerialization dataWithJSONObject:@{ @"sessionID":self.sessionID ?: @"", @"snapshotCount":@(index.count), @"snapshots":index, @"coverage":@"Observed screens only; not 100% app coverage." } options:NSJSONWritingPrettyPrinted error:error]; [idx writeToURL:[base URLByAppendingPathComponent:@"SESSION_INDEX.json"] options:NSDataWritingAtomic error:error]; [@"This session records screens actually observed and captured. It does not claim full app coverage.\n" writeToURL:[base URLByAppendingPathComponent:@"COVERAGE_REPORT.txt"] atomically:YES encoding:NSUTF8StringEncoding error:nil]; return base; }
@end

